int bp_nfc_qc(uint32_t cp)
{
    size_t lo = 0, hi = BP_QC_COUNT;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        if (cp < bp_qc_lo[mid]) {
            hi = mid;
        } else if (cp > bp_qc_hi[mid]) {
            lo = mid + 1;
        } else {
            return (int)bp_qc_val[mid];
        }
    }
    return 1; /* Yes */
}


