{
    size_t lo = 0, hi = BP_DECOMP_COUNT;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        uint32_t key = bp_decomp_cp[mid];
        if (cp < key) {
            hi = mid;
        } else if (cp > key) {
            lo = mid + 1;
        } else {
            unsigned n = bp_decomp_len[mid];
            unsigned off = bp_decomp_off[mid];
            unsigned i;
            for (i = 0; i < n; i++) {
                out[i] = bp_decomp_pool[off + i];
            }
            return (int)n;
        }
    }
    return 0;
}


