uint32_t bp_compose(uint32_t a, uint32_t b)
{
    uint64_t key = ((uint64_t)a << 32) | (uint64_t)b;
    size_t lo = 0, hi = BP_COMPOSE_COUNT;
    while (lo < hi) {
        size_t mid = lo + (hi - lo) / 2;
        uint64_t k = bp_compose_key[mid];
        if (key < k) {
            hi = mid;
        } else if (key > k) {
            lo = mid + 1;
        } else {
            return bp_compose_val[mid];
        }
    }
    return 0;
}
